// Version A: compose independent wrappers
interface Service { handle(req: any): any }
class BaseService implements Service { handle(req: any) { return 'ok' } }
class LoggingWrapper implements Service { constructor(private s: Service){}
  handle(r: any){ console.log('in'); return this.s.handle(r) }
}
class MetricsWrapper implements Service { constructor(private s: Service){}
  handle(r: any){ /* metrics */ return this.s.handle(r) }
}
// Version B: single combined subclass
class CombinedService implements Service {
  constructor(private enableLogging: boolean, private enableMetrics: boolean){}
  handle(r: any){ /* conditional behavior branches */ return 'ok' }
}
